#!/usr/bin/env python3
"""
generate_audit_reorg.py

Nests the Audit domain to match Business's proven per-feature shape
(models/repositories/services/schemas/rules), the same convention already
used for business/loan_book/, business/business_profile/, etc.

    security/audit/
    |-- models/audit_event.py
    |-- repositories/audit_repository.py
    |-- services/audit_service.py       (ALSO fixes a real bug -- see below)
    |-- schemas/audit_schemas.py
    +-- rules/event_config.py

security/detection/ stays a sibling, untouched.
security/rules/thresholds.py stays where it is (general Auth threshold,
not audit-specific), untouched.

ALSO FIXES A REAL BUG while relocating audit_service.py: ASYNC-classified
audit events were silently failing to persist with
"RuntimeError: Working outside of application context", because the
deferred write ran on a background thread after the request's Flask
context had ended. register(app) now captures the real app and wraps
every deferred write in app.app_context() explicitly. Verified against
real Postgres with a genuine background thread, not simulated -- see
MIGRATION_NOTES for the full explanation and the new regression test.

Usage:
    python generate_audit_reorg.py --root .
    python generate_audit_reorg.py --root . --dry-run
    python generate_audit_reorg.py --root . --force

Without --force, existing files are SKIPPED (not overwritten). Files
that ARE overwritten get a .bak backup first.
"""

import argparse
import sys
from pathlib import Path

