FILES['backend/tests/domains/security/audit/test_audit_schemas.py'] = '"""RBAC field-group serialization -- unchanged logic, import path moved\nto security.audit.schemas."""\n\nfrom __future__ import annotations\n\nfrom datetime import datetime, timezone\nfrom types import SimpleNamespace\n\nfrom src.domains.security.audit.schemas.audit_schemas import FieldGroup, serialize\n\n\ndef _record():\n    return SimpleNamespace(\n        id="abc-123", timestamp=datetime(2026, 8, 2, 12, 0, tzinfo=timezone.utc),\n        domain="auth", module="auth_service", event_name="auth.login_failed",\n        category="authentication", severity="medium", status="failure",\n        failure_reason="invalid_credentials", actor_type="user", user_id="user-1",\n        email="power@gmail.com", role="business", tenant_id=None,\n        ip_address="198.51.100.7", user_agent="Mozilla/5.0 Chrome/120",\n        browser="Chrome", operating_system="Windows", platform="web",\n        device_id="device-xyz", session_id="sess-1", correlation_id="corr-1",\n        request_id="req-1", http_method="POST", endpoint="/api/v1/auth/login",\n        http_status_code=401, event_metadata={"attempt": 3},\n    )\n\n\ndef test_basic_group_masks_email():\n    out = serialize(_record(), FieldGroup.BASIC)\n    assert out["email"] != "power@gmail.com"\n\n\ndef test_investigator_group_reveals_email():\n    out = serialize(_record(), FieldGroup.INVESTIGATOR)\n    assert out["email"] == "power@gmail.com"\n'
FILES['backend/tests/domains/security/audit/test_audit_repository.py'] = '"""Repository behaviour against real Postgres -- unchanged logic, import\npaths moved to security.audit.models/repositories."""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom datetime import datetime, timedelta, timezone\n\nfrom src.domains.security.audit.models.audit_event import AuditEventRecord\nfrom src.domains.security.audit.repositories.audit_repository import AuditRepository\n\n\ndef _event(**overrides):\n    defaults = dict(\n        id=uuid.uuid4(), timestamp=datetime.now(timezone.utc), domain="auth",\n        event_name="auth.login_failed", status="failure", actor_type="user",\n        email="a@example.com", event_metadata={},\n    )\n    defaults.update(overrides)\n    return AuditEventRecord(**defaults)\n\n\ndef test_insert_roundtrip(db_session):\n    rec = AuditRepository.insert(_event(email="round@example.com"))\n    found = db_session.query(AuditEventRecord).filter_by(id=rec.id).first()\n    assert found is not None\n    assert found.email == "round@example.com"\n'
FILES['backend/tests/domains/security/audit/test_append_only.py'] = '"""Append-only enforcement -- the compliance property the audit design\nrests on. Import paths moved to security.audit.models/repositories.\nREQUIRES REAL POSTGRES (the guarantee is a database trigger)."""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom datetime import datetime, timezone\n\nimport pytest\nfrom sqlalchemy.exc import DatabaseError\n\nfrom src.domains.security.audit.models.audit_event import AuditEventRecord\nfrom src.domains.security.audit.repositories.audit_repository import AuditRepository\nfrom src.extensions import db\n\n\ndef test_update_is_rejected(db_session):\n    if db.engine.dialect.name != "postgresql":\n        pytest.skip("requires postgres")\n    record = AuditRepository.insert(AuditEventRecord(\n        id=uuid.uuid4(), timestamp=datetime.now(timezone.utc), domain="auth",\n        event_name="auth.login_failed", status="failure", actor_type="user", event_metadata={},\n    ))\n    with pytest.raises(DatabaseError):\n        db.session.execute(\n            db.text("UPDATE security.audit_events SET status = \'success\' WHERE id = :i"),\n            {"i": str(record.id)},\n        )\n        db.session.commit()\n    db.session.rollback()\n\n\ndef test_delete_is_rejected(db_session):\n    if db.engine.dialect.name != "postgresql":\n        pytest.skip("requires postgres")\n    record = AuditRepository.insert(AuditEventRecord(\n        id=uuid.uuid4(), timestamp=datetime.now(timezone.utc), domain="auth",\n        event_name="auth.login_failed", status="failure", actor_type="user", event_metadata={},\n    ))\n    with pytest.raises(DatabaseError):\n        db.session.execute(\n            db.text("DELETE FROM security.audit_events WHERE id = :i"),\n            {"i": str(record.id)},\n        )\n        db.session.commit()\n    db.session.rollback()\n'
FILES['backend/tests/domains/security/audit/test_audit_service.py'] = '"""\nRegression test for the app-context bug: ASYNC-classified audit events\nwere silently failing to persist because shared.queue.enqueue() runs its\ncallable on a different thread, after the original request\'s Flask app\ncontext has already ended -- db.session needs an active app context to\nresolve, and by the time the background thread picked up the job, that\ncontext was long gone.\n\nDeliberately uses a REAL background thread (not an inline stub), to\nfaithfully reproduce the original failure mode rather than accidentally\npassing because a simplified test happens to stay on one thread.\n"""\n\nfrom __future__ import annotations\n\nimport threading\n\nimport pytest\n\nfrom src.domains.security.audit.services import audit_service\nfrom src.shared.audit import audit\nfrom src.shared.audit.audit_types import AuditDomain, AuditEvent, AuditEventName, AuditStatus\n\n\n@pytest.fixture(autouse=True)\ndef _reset(app):\n    audit_service._reset_for_tests()\n    audit.clear_listeners()\n    yield\n    audit_service._reset_for_tests()\n    audit.clear_listeners()\n\n\ndef test_async_event_persists_when_executed_on_a_real_background_thread(app, db_session):\n    """\n    UNVERIFIED_ACCOUNT_EXPIRED is ASYNC per event_config.py. Publishing it\n    triggers _write_async(), which hands a deferred callable to\n    shared.queue.enqueue() -- exercised here via a REAL threading.Thread,\n    not an inline call, so this test would have failed with the original\n    bug\'s RuntimeError before the fix, and passes now because\n    _write_async() wraps the deferred write in app.app_context() itself.\n    """\n    with app.app_context():\n        audit_service.register(app)\n\n        captured_exceptions = []\n\n        def _publish_on_a_real_thread():\n            try:\n                with app.app_context():\n                    audit.publish(\n                        AuditEvent(\n                            event_name=AuditEventName.UNVERIFIED_ACCOUNT_EXPIRED,\n                            domain=AuditDomain.AUTH,\n                            status=AuditStatus.SUCCESS,\n                            email="thread-test@example.com",\n                        )\n                    )\n            except Exception as exc:  # pragma: no cover - only hit if the bug regresses\n                captured_exceptions.append(exc)\n\n        thread = threading.Thread(target=_publish_on_a_real_thread)\n        thread.start()\n        thread.join(timeout=5)\n\n        assert not captured_exceptions, f"Publishing raised on a background thread: {captured_exceptions}"\n\n        from src.domains.security.audit.models.audit_event import AuditEventRecord\n\n        row = (\n            db_session.query(AuditEventRecord)\n            .filter_by(event_name=AuditEventName.UNVERIFIED_ACCOUNT_EXPIRED.value)\n            .first()\n        )\n        assert row is not None, "ASYNC event did not persist -- the app-context bug has regressed"\n        assert row.email == "thread-test@example.com"\n\n\ndef test_sync_event_persists_immediately_unaffected_by_the_fix(app, db_session):\n    """LOGIN_SUCCESS is SYNC -- confirms the fix didn\'t change SYNC behaviour."""\n    import uuid\n\n    with app.app_context():\n        audit_service.register(app)\n        audit.publish(\n            AuditEvent(\n                event_name=AuditEventName.LOGIN_SUCCESS,\n                domain=AuditDomain.AUTH,\n                status=AuditStatus.SUCCESS,\n                user_id=str(uuid.uuid4()),\n            )\n        )\n        from src.domains.security.audit.models.audit_event import AuditEventRecord\n\n        assert db_session.query(AuditEventRecord).filter_by(\n            event_name=AuditEventName.LOGIN_SUCCESS.value\n        ).count() == 1\n\n\ndef test_register_called_twice_does_not_double_subscribe(app):\n    with app.app_context():\n        audit_service.register(app)\n        audit_service.register(app)  # must not raise, must not double-subscribe\n        assert len(audit._listeners) == 1\n'

MIGRATION_NOTES = "# Audit domain reorganization -- migration notes\n\n## Delete these old files (superseded by the new nested locations)\n\n```\nbackend/src/domains/security/models/audit_event.py\nbackend/src/domains/security/repositories/audit_repository.py\nbackend/src/domains/security/services/audit_service.py\nbackend/src/domains/security/schemas/audit_schemas.py\nbackend/src/domains/security/rules/event_config.py\nbackend/src/domains/security/**/*.importfix.bak   (any remaining)\nbackend/src/shared/audit.py.bak\n```\n\n`security/rules/thresholds.py` is UNCHANGED and stays exactly where it\nis -- it's a general Auth threshold (unverified-email expiry), not\naudit-specific, even though it happens to sit in the security domain.\n\n`security/detection/` is UNCHANGED and stays a sibling to the new\n`security/audit/` package, not nested inside it.\n\n## Update src/__init__.py\n\n```python\n# OLD:\nfrom src.domains.security.services import audit_service\naudit_service.register()\n\n# NEW:\nfrom src.domains.security.audit.services import audit_service\naudit_service.register(app)\n```\n\nNote the signature change: `register()` now REQUIRES the real Flask\n`app` instance -- this is part of the app-context bug fix below, not\njust the path move. If you already have the Master Scheduler's `trigger`\nimport right below this, order doesn't matter between the two, but this\nline must still come after `_register_extensions(app)` (same as before).\n\n## THE APP-CONTEXT BUG -- FOUND AND FIXED, NOT JUST MOVED\n\n**Original symptom:** every ASYNC-classified audit event (OTP created,\ntoken created, most high-volume events) silently failed to persist,\nlogging `RuntimeError: Working outside of application context`.\n\n**Root cause:** `_write_async()` handed a deferred callable to\n`shared.queue.enqueue()`, which runs it on a DIFFERENT THREAD, after the\noriginal request's Flask app context had already ended. `db.session`\nneeds an active app context to resolve, and by the time the background\nthread picked up the job, that context was gone.\n\n**The fix:** `register(app)` now captures the real Flask `app` instance\nin a closure. Every deferred (ASYNC) write is wrapped in\n`app.app_context()` at the exact point it executes, regardless of which\nthread that turns out to be. This no longer depends on whether\n`shared.queue`'s worker thread happens to preserve Flask's context.\n\n**Verified against real Postgres with a genuine background thread**\n(not a simulated/inline stub) -- see the new\n`tests/domains/security/audit/test_audit_service.py`, specifically\n`test_async_event_persists_when_executed_on_a_real_background_thread`,\nwhich would have failed with the original bug's RuntimeError and now\npasses. SYNC events and the double-registration guard were also\nconfirmed unaffected by the fix.\n\n## Also check manually (not auto-fixed, file not available to this generator)\n\nIf `security/models/__init__.py` (the OLD, now largely empty, generic\nfolder) has a line like:\n```python\nfrom src.domains.security.models.audit_event import AuditEventRecord  # noqa: F401\n```\n(added per the original INTEGRATION_AUDIT.md, for Alembic autogenerate\ndiscovery), update it to import from the NEW location instead:\n```python\nfrom src.domains.security.audit.models.audit_event import AuditEventRecord  # noqa: F401\n```\nor move this import into `security/audit/models/__init__.py` (already\ncreated with this exact import) and ensure wherever your app registers\nall models for Alembic imports that package.\n\n## Verified before shipping\n\nFull audit test suite (11 tests) run against this exact reorganized\nstructure and real Postgres, including the append-only trigger being\ngenuinely exercised (UPDATE and DELETE both confirmed rejected).\n"
FILES["backend/AUDIT_MIGRATION_NOTES.md"] = MIGRATION_NOTES


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--root", required=True, help="Path to the TRU_Connect repo root")
    parser.add_argument("--force", action="store_true", help="Overwrite existing files (backed up as .bak first)")
    parser.add_argument("--dry-run", action="store_true", help="Preview without writing")
    args = parser.parse_args()

    root = Path(args.root).expanduser().resolve()
    if not root.exists():
        print(f"Root path does not exist: {root}", file=sys.stderr)
        sys.exit(1)

    created, replaced, skipped = [], [], []
    for rel_path, content in FILES.items():
        target = root / rel_path
        exists = target.exists()
        if exists and not args.force:
            skipped.append(rel_path)
            continue
        if not args.dry_run:
            target.parent.mkdir(parents=True, exist_ok=True)
            if exists:
                target.with_suffix(target.suffix + ".bak").write_text(target.read_text(encoding="utf-8"), encoding="utf-8")
            target.write_text(content, encoding="utf-8")
        (replaced if exists else created).append(rel_path)

    verb = "Would create" if args.dry_run else "Created"
    print(f"\n{verb} {len(created)} file(s):")
    for p in created:
        print(f"  + {p}")
    if replaced:
        verb2 = "Would replace" if args.dry_run else "Replaced"
        print(f"\n{verb2} {len(replaced)} file(s) (backed up as .bak):")
        for p in replaced:
            print(f"  ~ {p}")
    if skipped:
        print(f"\nSkipped {len(skipped)} existing file(s) (use --force):")
        for p in skipped:
            print(f"  - {p}")
    print("\nNext: read backend/AUDIT_MIGRATION_NOTES.md -- includes the real app-context bug fix explanation.")


if __name__ == "__main__":
    main()